// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner) public {
        vm.startPrank(address(this));
        c.setOwner(address(this));
        bool ok = true;
        try c.setOwner(_owner) { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(!ok || c.owner() == _owner);
    }
}
